// NFT artwork, served as responsive AVIF/WebP from /nfts (generated by scripts/build-images.mjs).
// The API gives an image id like 'figma/emerald-ape'; files are /nfts/<id>-<width>.<format>.
import { cn } from './lib/utils'

export const NFT_IMAGE_WIDTHS = [320, 640, 960] as const

const srcSet = (image: string, format: 'avif' | 'webp') =>
  NFT_IMAGE_WIDTHS.map((w) => `/nfts/${image}-${w}.${format} ${w}w`).join(', ')

export function NftImage({
  image,
  alt,
  sizes = '(min-width: 768px) 320px, 50vw',
  priority = false,
  className,
}: {
  image: string
  alt: string
  /** How wide the image renders, so the browser picks the right file. */
  sizes?: string
  /** For the largest above-the-fold image (LCP): load eagerly with high priority. */
  priority?: boolean
  className?: string
}) {
  return (
    <picture>
      <source type="image/avif" srcSet={srcSet(image, 'avif')} sizes={sizes} />
      <source type="image/webp" srcSet={srcSet(image, 'webp')} sizes={sizes} />
      <img
        src={`/nfts/${image}-640.webp`}
        alt={alt}
        width={640}
        height={640}
        loading={priority ? 'eager' : 'lazy'}
        decoding="async"
        fetchPriority={priority ? 'high' : 'auto'}
        className={cn('aspect-square w-full rounded-xl object-cover', className)}
      />
    </picture>
  )
}
